ordered_claim_predicates.measurement_source:
function featureGateOff(evidence) {
  return evidence.route_feature_enabled === false;
}

function liveRouteZeroCorpusReads(evidence, context) {
  return sameClosedStringSet(
    evidence.method_probes.map((probe) => probe.method),
    MARKET_STATS_METHODS,
  ) && evidence.method_probes.every((probe) => (
    probe.member_id === `${probe.method} /api/market-stats`
    && probe.route_id === '/api/market-stats'
    && probe.status === 503
    && probe.error_code === 'MARKET_STATS_DISABLED'
    && /private/i.test(probe.cache_control)
    && /no-store/i.test(probe.cache_control)
    && probe.database_calls === 0
    && probe.corpus_reads === 0
    && probe.retry_after === null
    && probe.code_commit === context.codeCommit
    && probe.runtime_deployment_id === evidence.runtime_deployment_id
    && probe.environment === context.environment
    && probe.observed_at === context.observed_at
  ));
}

function containmentTestPass(evidence, context) {
  return sameClosedStringSet(
    evidence.tests.map((entry) => entry.test_id),
    REQUIRED_CONTAINMENT_TEST_IDS,
  ) && evidence.tests.every((entry) => (
    entry.exit_code === 0
    && entry.code_commit === context.codeCommit
    && entry.environment === context.environment
    && Date.parse(entry.completed_at) <= Date.parse(context.observed_at)
  ));
}

function sourceBuiltAndRuntimeRouteInventoriesEqual(evidence) {
  return sameClosedStringSet(evidence.source_route_ids, evidence.built_route_ids)
    && sameClosedStringSet(evidence.source_route_ids, evidence.runtime_route_ids);
}

function everyBroadRouteContained(evidence, context) {
  return sameClosedStringSet(
    evidence.source_route_ids,
    evidence.routes.map((route) => route.member_id),
  )
    && evidence.routes.every((route) => (
      route.source_contained === true
      && route.built_contained === true
      && route.runtime_contained === true
      && route.runtime_status === 503
      && (
        route.runtime_error_code === 'ROUTE_CONTAINED'
        || (route.method === 'HEAD' && route.runtime_error_code === null)
      )
      && route.database_calls === 0
      && route.corpus_reads === 0
      && route.code_commit === context.codeCommit
      && route.runtime_deployment_id === evidence.runtime_deployment_id
      && route.environment === context.environment
      && route.observed_at === context.observed_at
    ))
    && containmentTestPass(evidence, context);
}

function zeroBroadNodeFallback(evidence) {
  return evidence.routes.every((route) => (
    route.node_corpus_reads === 0
    && route.legacy_fallback_used === false
  ));
}

function ownerAndPurposeRecordedWithoutSecret(evidence) {
  return isNonEmptyString(evidence.process_identity_digest)
    && isNonEmptyString(evidence.owner)
    && isNonEmptyString(evidence.purpose)
    && evidence.secret_field_count === 0;
}

function recognisedOrRotationRequired(evidence) {
  return (
    evidence.recognition_status === 'RECOGNISED'
    && evidence.rotation_required === false
  ) || (
    evidence.recognition_status === 'UNRECOGNISED'
    && evidence.rotation_required === true
    && evidence.rotation_completed === true
  );
}

function compromisedCredentialsRevoked(evidence) {
  return sameClosedStringSet(evidence.compromised_credential_ids, evidence.revoked_ids);
}

function replacementActivationVerified(evidence) {
  return isTimestamp(evidence.replacement_activation_verified_at);
}

function noSecretInEvidence(evidence) {
  return evidence.secret_field_count === 0;
}

function rotationVerifiedOrRecognisedTrafficNaWithBenApproval(evidence, context) {
  if (
    evidence.disposition === 'ROTATED'
    && isTimestamp(evidence.rotation_verified_at)
    && evidence.zayo_disposition_id === null
    && evidence.ben_approval_id === null
  ) return true;
  if (evidence.disposition !== 'RECOGNISED_TRAFFIC_APPROVED_NA'
    || evidence.rotation_verified_at !== null
    || !isDigest(evidence.zayo_disposition_id)
    || !isDigest(evidence.ben_approval_id)) return false;
  const zayo = memberFor(
    context,
    `zayo:${evidence.zayo_disposition_id}`,
    'ZayoTrafficDisposition',
  );
  const approval = memberFor(
    context,
    `approval:${evidence.ben_approval_id}`,
    'SupabaseSecretNaApproval',
  );
  const {
    approval_id: approvalId,
    signature: approvalSignature,
    ...approvalIdentityPayload
  } = approval || {};
  void approvalSignature;
  if (!zayo
    || !approval
    || zayo.gate_id !== 'G0_ZAYO_DISPOSITION'
    || zayo.attestation_source_digest !== evidence.attestation_source_digest
    || zayo.recognition_status !== 'RECOGNISED'
    || zayo.rotation_required !== false
    || zayo.purpose !== 'AUTHORISED_DATABASE_TRAFFIC'
    || context.domainDigest(
      'PROGRAMME_GATE_ZAYO_DISPOSITION_ID/V1',
      zayo,
    ) !== evidence.zayo_disposition_id
    || approval.approval_id !== evidence.ben_approval_id
    || approval.supabase_attestation_source_digest !== evidence.attestation_source_digest
    || approval.zayo_process_identity_digest !== zayo.process_identity_digest
    || approval.approved_disposition !== evidence.disposition
    || approval.approver_identity !== 'BEN_GOODCHILD'
    || approval.conditions.length !== 0
    || context.domainDigest(
      'PROGRAMME_GATE_SUPABASE_SECRET_NA_APPROVAL_ID/V1',
      approvalIdentityPayload,
    ) !== approvalId) return false;
  return signatureIsValid(context, {
    record: approval,
    signatureField: 'signature',
    keyId: approval.approver_key_id,
    role: 'BEN_APPROVER',
    domain: 'PROGRAMME_GATE_SUPABASE_SECRET_NA_APPROVAL/V1',
  });
}

function noSecretInEvidence(evidence) {
  return evidence.secret_field_count === 0;
}

function distinctProjectAndCredentials(evidence) {
  return evidence.production_project_identity_digest !== evidence.staging_project_identity_digest
    && evidence.production_credential_identity_digest !== evidence.staging_credential_identity_digest;
}

function productionDmlDenied(evidence) {
  return evidence.production_dml_probe === 'DENIED';
}

function snapshotRestoreOnly(evidence) {
  return evidence.restore_mode === 'PRODUCTION_SNAPSHOT_ONLY';
}

function branchPreviewUsesStagingOnlyCredentials(evidence) {
  return isNonEmptyString(evidence.preview_deployment_id)
    && evidence.preview_credential_scope === 'STAGING_ONLY';
}

function productionAliasUnchanged(evidence) {
  return evidence.production_alias_before === evidence.production_alias_after;
}

function completePreviewRouteActionInventory(evidence) {
  const actions = evidence.preview_route_actions;
  return Array.isArray(actions)
    && new Set(actions.map((entry) => entry.action_id)).size === actions.length
    && sameClosedStringSet(
      actions.map((entry) => entry.action_class),
      PREVIEW_ACTION_CLASSES,
    );
}

function unauthenticatedAccessDeniedBeforeAndAfterRestore(evidence) {
  return completePreviewRouteActionInventory(evidence)
    && evidence.preview_route_actions.every((entry) => (
      accessDenied(entry.unauthenticated_before_restore_status)
      && accessDenied(entry.unauthenticated_after_restore_status)
    ));
}

function authenticatedNonAdminPrivilegedActionsDenied(evidence) {
  return completePreviewRouteActionInventory(evidence)
    && evidence.preview_route_actions
      .filter((entry) => entry.action_class !== 'READ_ONLY_TEST')
      .every((entry) => accessDenied(entry.authenticated_non_admin_status));
}

function privilegedPreviewActionsDisabled(evidence) {
  return completePreviewRouteActionInventory(evidence)
    && evidence.preview_route_actions
      .filter((entry) => DISABLED_PREVIEW_ACTION_CLASSES.includes(entry.action_class))
      .every((entry) => (
        entry.feature_enabled === false
        && entry.authorised_test_status === null
      ));
}

function authorisedReadOnlyTestAccessPass(evidence) {
  return completePreviewRouteActionInventory(evidence)
    && evidence.preview_route_actions
      .filter((entry) => entry.action_class === 'READ_ONLY_TEST')
      .every((entry) => (
        entry.feature_enabled === true
        && entry.authorised_test_status >= 200
        && entry.authorised_test_status < 300
      ));
}

function fiveNamedLanesPassSameRoot(evidence, context) {
  return reviewSetFacts(evidence, context) !== null;
}

function eligibleLegalReviewer(evidence, context) {
  return reviewSetFacts(evidence, context)?.legalReviewerEligible === true;
}

function reviewerIndependenceRecomputed(evidence, context) {
  return reviewSetFacts(evidence, context) !== null;
}

function rootUnchangedBeforeAndAfter(evidence, context) {
  return reviewSetFacts(evidence, context) !== null;
}

function approvedRootEqualsPassingReviewRoot(evidence, context) {
  return benApprovalFacts(evidence, context) !== null;
}

function benIdentityAndSignatureValid(evidence, context) {
  return benApprovalFacts(evidence, context) !== null;
}

function approvalUnconditional(evidence, context) {
  return benApprovalFacts(evidence, context) !== null;
}

function freezeGateApproved(evidence, context) {
  const members = contractFreezeMembers(evidence, context);
  return Boolean(members)
    && contractAuthorityManifestMatches(evidence, context, members.authorityManifest)
    && members.approval.approval_id === evidence.freeze_gate_approval_id
    && members.approval.authority_manifest_id
      === evidence.contract_authority_manifest_id
    && members.approval.frozen_contract_pair_digest === evidence.frozen_contract_pair_digest
    && evidence.ben_bundle_approval_evidence_id === members.approval.approval_id
    && members.approval.approver_identity === 'BEN_GOODCHILD'
    && members.approval.conditions.length === 0
    && signatureIsValid(context, {
      record: members.approval,
      signatureField: 'signature',
      keyId: members.approval.approver_key_id,
      role: 'BEN_APPROVER',
      domain: 'PROGRAMME_GATE_CONTRACT_FREEZE_APPROVAL/V1',
    });
}

function statusGenerationMatches(evidence, context) {
  const members = contractFreezeMembers(evidence, context);
  return Boolean(members)
    && members.status.specification_root === evidence.specification_root
    && members.status.code_commit === evidence.code_commit
    && members.status.environment === evidence.environment
    && members.status.generation === evidence.status_generation
    && signatureIsValid(context, {
      record: members.status,
      signatureField: 'signature',
      keyId: members.status.validator_key_id,
      role: 'STATUS_PUBLISHER',
      domain: 'PROGRAMME_GATE_STATUS/V2',
    })
    && context.domainDigest(
      'PROGRAMME_GATE_STATUS_ARTEFACT_PAYLOAD/V2',
      members.status,
    ) === evidence.status_payload_digest;
}

runtime_source_modules.utf8_source:
const Ajv = require('ajv');

const HEX_64 = '^[a-f0-9]{64}$';
const BASE64 = '^[A-Za-z0-9+/]+={0,2}$';
const TOKEN = '^[A-Z][A-Z0-9_./:-]{0,127}$';
const LOWER_ID = '^[a-z0-9][a-z0-9_./:-]{0,127}$';
const TYPE_ID = '^[A-Za-z][A-Za-z0-9_./:-]{0,127}$';

function closedObject(properties, required = Object.keys(properties)) {
  return {
    type: 'object',
    additionalProperties: false,
    required,
    properties,
  };
}

const digest = { type: 'string', pattern: HEX_64 };
const codeCommit = { type: 'string', pattern: '^[a-f0-9]{40}$' };
const token = { type: 'string', pattern: TOKEN };
const lowerId = { type: 'string', pattern: LOWER_ID };
const typeId = { type: 'string', pattern: TYPE_ID };
const nonEmptyString = { type: 'string', minLength: 1 };
const timestamp = { type: 'string', format: 'canonical-utc-timestamp' };
const environment = { enum: ['STAGING', 'PRODUCTION'] };
const stringSet = {
  type: 'array',
  uniqueItems: true,
  items: nonEmptyString,
};
const trustedReviewTaskManifestSchema = closedObject({
  manifest_version: { const: 'TrustedReviewTaskManifest/V1' },
  lane_id: token,
  exact_specification_root: digest,
  frozen_specification: closedObject({
    manifest_id: nonEmptyString,
    manifest_digest: digest,
    file_count: { type: 'integer', minimum: 1 },
    immutable: { const: true },
  }),
  registered_prompt: closedObject({
    prompt_id: token,
    path: nonEmptyString,
    payload_digest: digest,
    byte_length: { type: 'integer', minimum: 1 },
    immutable: { const: true },
    contains_prior_review_conclusions: { const: false },
  }),
  output_schema: closedObject({
    schema_id: nonEmptyString,
    path: nonEmptyString,
    payload_digest: digest,
    byte_length: { type: 'integer', minimum: 1 },
    immutable: { const: true },
  }),
});
const trustedReviewRuntimeContextSchema = closedObject({
  context_version: { const: 'TrustedReviewRuntimeContext/V1' },
  review_runtime_binary_path: nonEmptyString,
  review_runtime_version: nonEmptyString,
  review_runtime_binary_digest: digest,
  working_directory: nonEmptyString,
  operating_system: nonEmptyString,
  architecture: nonEmptyString,
  home_path: nonEmptyString,
  codex_home_path: nonEmptyString,
  tmpdir_path: nonEmptyString,
  path_value: nonEmptyString,
  lang: nonEmptyString,
  lc_all: nonEmptyString,
  term: nonEmptyString,
});

const claimValueSchema = {
  oneOf: [
    { type: 'boolean' },
    { type: 'integer' },
    { type: 'number' },
    { type: 'string' },
    { type: 'null' },
  ],
};

const exactAcceptanceClaimSchema = closedObject({
  claim_key: lowerId,
  result_type: { enum: ['BOOLEAN', 'INTEGER', 'NUMBER', 'STRING', 'NULL'] },
  typed_value: claimValueSchema,
});

const claimPredicateSchema = closedObject({
  claim_key: lowerId,
  result_type: { enum: ['BOOLEAN', 'INTEGER', 'NUMBER', 'STRING', 'NULL'] },
  exact_input_member_types_and_paths: {
    type: 'array',
    minItems: 1,
    items: closedObject({
      member_type: typeId,
      json_pointer: { type: 'string', pattern: '^(/([^/~]|~[01])*)*$' },
    }),
  },
  measurement_executable_digest: digest,
  measurement_configuration_digest: digest,
  comparison_operator: {
    enum: ['EQUALS', 'NOT_EQUALS', 'GREATER_THAN', 'GREATER_THAN_OR_EQUALS', 'LESS_THAN', 'LESS_THAN_OR_EQUALS'],
  },
  expected_typed_value: claimValueSchema,
});

const containedRouteMethodProbeSchema = closedObject({
  schema_version: { const: 'ContainedRouteMethodProbe/V1' },
  member_id: nonEmptyString,
  route_id: nonEmptyString,
  method: { enum: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS', 'HEAD'] },
  status: { type: 'integer', minimum: 100, maximum: 599 },
  error_code: token,
  cache_control: nonEmptyString,
  retry_after: { oneOf: [nonEmptyString, { type: 'null' }] },
  database_calls: { type: 'integer', minimum: 0 },
  corpus_reads: { type: 'integer', minimum: 0 },
  code_commit: codeCommit,
  runtime_deployment_id: nonEmptyString,
  environment,
  observed_at: timestamp,
});

const broadRouteActionObservationSchema = closedObject({
  schema_version: { const: 'BroadRouteActionObservation/V1' },
  member_id: nonEmptyString,
  route_id: nonEmptyString,
  method: { enum: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS', 'HEAD'] },
  containment_class: {
    enum: ['QUERY_ROUTE', 'BROAD_CORPUS_ACTION', 'PUBLIC_SERVICE_ACTION'],
  },
  source_contained: { type: 'boolean' },
  built_contained: { type: 'boolean' },
  runtime_contained: { type: 'boolean' },
  runtime_status: { type: 'integer', minimum: 100, maximum: 599 },
  runtime_error_code: { oneOf: [token, { type: 'null' }] },
  database_calls: { type: 'integer', minimum: 0 },
  corpus_reads: { type: 'integer', minimum: 0 },
  node_corpus_reads: { type: 'integer', minimum: 0 },
  legacy_fallback_used: { type: 'boolean' },
  code_commit: codeCommit,
  runtime_deployment_id: nonEmptyString,
  environment,
  observed_at: timestamp,
});

const programmeGateTestExecutionRecordSchema = closedObject({
  schema_version: { const: 'ProgrammeGateTestExecutionRecord/V1' },
  test_id: token,
  code_commit: codeCommit,
  environment,
  command_digest: digest,
  executable_digest: digest,
  started_at: timestamp,
  completed_at: timestamp,
  exit_code: { type: 'integer' },
  output_digest: digest,
});

const schemas = Object.freeze({
  'ContainedRouteMethodProbe/V1': {
    $id: 'ContainedRouteMethodProbe/V1',
    ...containedRouteMethodProbeSchema,
  },

  'BroadRouteActionObservation/V1': {
    $id: 'BroadRouteActionObservation/V1',
    ...broadRouteActionObservationSchema,
  },

  'ProgrammeGateTestExecutionRecord/V1': {
    $id: 'ProgrammeGateTestExecutionRecord/V1',
    ...programmeGateTestExecutionRecordSchema,
  },

  'MarketStatsContainmentAttestation/V1': {
    $id: 'MarketStatsContainmentAttestation/V1',
    ...closedObject({
      schema_version: { const: 'MarketStatsContainmentAttestation/V1' },
      gate_id: { const: 'G0_MARKET_STATS_CONTAINED' },
      code_commit: codeCommit,
      runtime_deployment_id: nonEmptyString,
      environment,
      observed_at: timestamp,
      route_feature_enabled: { const: false },
      method_probes: {
        type: 'array',
        minItems: 1,
        uniqueItems: true,
        items: containedRouteMethodProbeSchema,
      },
      tests: {
        type: 'array',
        minItems: 1,
        uniqueItems: true,
        items: programmeGateTestExecutionRecordSchema,
      },
    }),
  },

  'BroadRouteContainmentAttestation/V1': {
    $id: 'BroadRouteContainmentAttestation/V1',
    ...closedObject({
      schema_version: { const: 'BroadRouteContainmentAttestation/V1' },
      gate_id: { const: 'G0_BROAD_CORPUS_ROUTES_CONTAINED' },
      code_commit: codeCommit,
      runtime_deployment_id: nonEmptyString,
      environment,
      observed_at: timestamp,
      source_route_ids: stringSet,
      built_route_ids: stringSet,
      runtime_route_ids: stringSet,
      routes: {
        type: 'array',
        minItems: 1,
        uniqueItems: true,
        items: broadRouteActionObservationSchema,
      },
      tests: {
        type: 'array',
        minItems: 1,
        uniqueItems: true,
        items: programmeGateTestExecutionRecordSchema,
      },
    }),
  },

  'ZayoTrafficDisposition/V1': {
    $id: 'ZayoTrafficDisposition/V1',
    ...closedObject({
      schema_version: { const: 'ZayoTrafficDisposition/V1' },
      gate_id: { const: 'G0_ZAYO_DISPOSITION' },
      code_commit: codeCommit,
      environment,
      observed_at: timestamp,
      attestation_source_digest: digest,
      process_identity_digest: digest,
      owner: nonEmptyString,
      purpose: nonEmptyString,
      recognition_status: { enum: ['RECOGNISED', 'UNRECOGNISED'] },
      rotation_required: { type: 'boolean' },
      rotation_completed: { type: 'boolean' },
      secret_field_count: { const: 0 },
    }),
  },

  'ClaudeCredentialRotationReceipt/V1': {
    $id: 'ClaudeCredentialRotationReceipt/V1',
    ...closedObject({
      schema_version: { const: 'ClaudeCredentialRotationReceipt/V1' },
      gate_id: { const: 'G0_CLAUDE_CREDENTIAL_ROTATION' },
      code_commit: codeCommit,
      environment,
      observed_at: timestamp,
      attestation_source_digest: digest,
      compromised_credential_ids: {
        type: 'array',
        minItems: 1,
        uniqueItems: true,
        items: digest,
      },
      revoked_ids: {
        type: 'array',
        minItems: 1,
        uniqueItems: true,
        items: digest,
      },
      replacement_activation_verified_at: timestamp,
      secret_field_count: { const: 0 },
    }),
  },

  'SupabaseSecretDisposition/V1': {
    $id: 'SupabaseSecretDisposition/V1',
    ...closedObject({
      schema_version: { const: 'SupabaseSecretDisposition/V1' },
      gate_id: { const: 'G0_SUPABASE_SECRET_DISPOSITION' },
      code_commit: codeCommit,
      environment,
      observed_at: timestamp,
      attestation_source_digest: digest,
      disposition: { enum: ['ROTATED', 'RECOGNISED_TRAFFIC_APPROVED_NA'] },
      rotation_verified_at: { oneOf: [timestamp, { type: 'null' }] },
      zayo_disposition_id: { oneOf: [digest, { type: 'null' }] },
      ben_approval_id: { oneOf: [digest, { type: 'null' }] },
      secret_field_count: { const: 0 },
    }),
  },

  'SupabaseSecretNaApproval/V1': {
    $id: 'SupabaseSecretNaApproval/V1',
    ...closedObject({
      schema_version: { const: 'SupabaseSecretNaApproval/V1' },
      approval_id: digest,
      supabase_attestation_source_digest: digest,
      zayo_process_identity_digest: digest,
      approved_disposition: { const: 'RECOGNISED_TRAFFIC_APPROVED_NA' },
      approver_identity: { const: 'BEN_GOODCHILD' },
      conditions: {
        type: 'array',
        maxItems: 0,
      },
      approved_at: timestamp,
      signature_algorithm: { const: 'Ed25519' },
      approver_key_id: token,
      signature: { type: 'string', pattern: BASE64, minLength: 1 },
    }),
  },

  'StagingSupabaseIsolationAttestation/V1': {
    $id: 'StagingSupabaseIsolationAttestation/V1',
    ...closedObject({
      production_project_identity_digest: digest,
      staging_project_identity_digest: digest,
      production_credential_identity_digest: digest,
      staging_credential_identity_digest: digest,
      production_dml_probe: { const: 'DENIED' },
      restore_mode: { const: 'PRODUCTION_SNAPSHOT_ONLY' },
    }),
  },

  'StagingVercelIsolationAttestation/V1': {
    $id: 'StagingVercelIsolationAttestation/V1',
    ...closedObject({
      preview_deployment_id: nonEmptyString,
      preview_credential_scope: { const: 'STAGING_ONLY' },
      production_alias_before: nonEmptyString,
      production_alias_after: nonEmptyString,
    }),
  },

  'StagingAccessProtectionAttestation/V1': {
    $id: 'StagingAccessProtectionAttestation/V1',
    ...closedObject({
      preview_route_actions: {
        type: 'array',
        minItems: 9,
        uniqueItems: true,
        items: closedObject({
          action_id: token,
          action_class: {
            enum: [
              'READ_ONLY_TEST',
              'ADMIN_PRIVILEGED',
              'WRITER',
              'INGEST',
              'CORRECTION',
              'EXPORT',
              'IMPORT',
              'PROMOTION',
              'CUTOVER',
            ],
          },
          unauthenticated_before_restore_status: {
            type: 'integer',
            minimum: 100,
            maximum: 599,
          },
          unauthenticated_after_restore_status: {
            type: 'integer',
            minimum: 100,
            maximum: 599,
          },
          authenticated_non_admin_status: {
            type: 'integer',
            minimum: 100,
            maximum: 599,
          },
          authorised_test_status: {
            oneOf: [
              { type: 'integer', minimum: 100, maximum: 599 },
              { type: 'null' },
            ],
          },
          feature_enabled: { type: 'boolean' },
        }),
      },
    }),
  },

  'ProgrammeGateAcceptanceDefinition/V1': {
    $id: 'ProgrammeGateAcceptanceDefinition/V1',
    ...closedObject({
      schema_version: { const: 'ProgrammeGateAcceptanceDefinition/V1' },
      definition_id: digest,
      definition_digest: digest,
      evidence_contract: lowerId,
      specification_root: digest,
      frozen_contract_pair_digest: { oneOf: [digest, { type: 'null' }] },
      evidence_object_json_schema_id: nonEmptyString,
      evidence_object_json_schema_digest: digest,
      evidence_subject_type: typeId,
      evidence_subject_identity_fields: {
        type: 'array',
        minItems: 1,
        uniqueItems: true,
        items: lowerId,
      },
      immutable_member_universe_definition: closedObject({
        universe_id: token,
        ordering_rule: token,
        duplicate_effect: { const: 'OPEN' },
        missing_or_extra_effect: { const: 'OPEN' },
      }),
      immutable_member_json_schema_set_digest: digest,
      member_enumerator_executable_digest: digest,
      member_enumerator_configuration_digest: digest,
      ordered_claim_predicate_definitions: {
        type: 'array',
        minItems: 1,
        items: claimPredicateSchema,
      },
    }),
  },

  'ProgrammeGateEvidenceEnvelope/V2': {
    $id: 'ProgrammeGateEvidenceEnvelope/V2',
    ...closedObject({
